import { Controller } from "@hotwired/stimulus"

// HTTP polling, not WebSockets. Crowded conference Wi-Fi often drops sockets,
// and a shared proxy must not cache one player's page for someone else.
// The state endpoint long-polls when wait=1, so a question opens on every
// screen within a few milliseconds of the moderator.
export default class extends Controller {
  static targets = ["body", "controls"]
  static values = {
    url: String,
    version: Number,
    phaseKey: String,
    interval: { type: Number, default: 80 }
  }

  connect() {
    this.alive = true
    this.busy = false
    this.inflight = false
    this.finishing = false
    this.clockOffset = null
    this.delay = this.intervalValue
    this.onSubmit = (event) => this.submit(event)
    this.onVisible = () => this.wake()
    this.element.addEventListener("submit", this.onSubmit)
    document.addEventListener("visibilitychange", this.onVisible)
    window.addEventListener("pageshow", this.onVisible)
    this.armTimer()
    this.wake()
  }

  disconnect() {
    this.alive = false
    clearTimeout(this.timer)
    clearTimeout(this.timerTick)
    this.element.removeEventListener("submit", this.onSubmit)
    document.removeEventListener("visibilitychange", this.onVisible)
    window.removeEventListener("pageshow", this.onVisible)
  }

  wake() {
    if (!this.alive || document.hidden) return
    this.delay = this.intervalValue
    clearTimeout(this.timer)
    this.poll()
  }

  schedule() {
    if (!this.alive) return
    clearTimeout(this.timer)
    this.timer = setTimeout(() => this.poll(), this.delay)
  }

  async poll() {
    if (!this.alive || this.inflight || this.busy) {
      if (this.alive && !this.inflight) this.schedule()
      return
    }
    this.inflight = true
    const abort = new AbortController()
    const timeout = setTimeout(() => abort.abort(), 12000)
    try {
      const url = new URL(this.urlValue, window.location.href)
      url.searchParams.set("phase_key", this.phaseKeyValue || "")
      url.searchParams.set("version", String(this.versionValue ?? 0))
      url.searchParams.set("wait", "1")
      url.searchParams.set("_", Date.now().toString())
      const response = await fetch(url, {
        headers: { Accept: "application/json" },
        cache: "no-store",
        credentials: "same-origin",
        signal: abort.signal
      })
      if (!response.ok) throw new Error(String(response.status))
      this.applyPoll(await response.json())
      this.delay = document.hidden ? Math.max(this.intervalValue, 2000) : this.intervalValue
    } catch (_error) {
      this.delay = Math.min(Math.max(this.delay, this.intervalValue) * 2, 5000)
    } finally {
      clearTimeout(timeout)
      this.inflight = false
      this.schedule()
    }
  }

  applyPoll(data) {
    const version = Number(data.version)
    if (Number.isFinite(version) && version < this.versionValue) return
    if (Number.isFinite(version)) this.versionValue = version

    if (data.phase_key && data.phase_key !== this.phaseKeyValue && data.body_html != null) {
      this.phaseKeyValue = data.phase_key
      this.applyHtml(data)
      return
    }

    this.noteTimer(data.timer)
    this.updateCounters(data.counters)
    this.paintTimer()
  }

  applyFull(data) {
    const version = Number(data.version)
    if (Number.isFinite(version) && version < this.versionValue) return
    if (Number.isFinite(version)) this.versionValue = version
    if (data.phase_key) this.phaseKeyValue = data.phase_key
    this.applyHtml(data)
    this.noteTimer(data.timer)
    this.updateCounters(data.counters)
    this.paintTimer()
  }

  applyHtml(data) {
    if (data.body_html != null && this.hasBodyTarget) this.bodyTarget.innerHTML = data.body_html
    if (data.controls_html != null && this.hasControlsTarget) this.controlsTarget.innerHTML = data.controls_html
    if (data.cover_class) this.element.className = data.cover_class
    this.armTimer()
  }

  updateCounters(counters) {
    if (!counters) return
    Object.entries(counters).forEach(([key, text]) => {
      this.element.querySelectorAll(`[data-counter="${CSS.escape(key)}"]`).forEach((element) => {
        if (element.textContent !== text) element.textContent = text
      })
    })
  }

  armTimer() {
    clearTimeout(this.timerTick)
    this.timerTick = null
    this.clockOffset = null
    this.finishing = false
    this.paintTimer()
  }

  noteTimer(timer) {
    if (!timer || timer.deadline_ms == null) return
    this.element.querySelectorAll("[data-timer-deadline]").forEach((node) => {
      node.dataset.timerDeadline = String(timer.deadline_ms)
      if (timer.server_now_ms != null) node.dataset.timerServerNow = String(timer.server_now_ms)
    })
    if (timer.server_now_ms != null) this.clockOffset = Number(timer.server_now_ms) - Date.now()
  }

  paintTimer() {
    if (!this.alive) return
    const node = this.element.querySelector("[data-timer-deadline]")
    if (!node) {
      clearTimeout(this.timerTick)
      this.timerTick = null
      return
    }

    const deadline = Number(node.dataset.timerDeadline)
    const serverNow = Number(node.dataset.timerServerNow)
    if (!Number.isFinite(deadline)) return
    if (this.clockOffset == null && Number.isFinite(serverNow)) {
      this.clockOffset = serverNow - Date.now()
    }

    const remaining = deadline - (Date.now() + (this.clockOffset || 0))
    const label = this.formatCountdown(remaining)
    this.element.querySelectorAll("[data-counter='timer']").forEach((element) => {
      if (element.textContent !== label) element.textContent = label
    })
    if (remaining <= 0) this.finishByTimer()

    const delay = remaining <= 0 ? 150 : Math.min(200, Math.max(40, remaining % 1000 || 1000))
    clearTimeout(this.timerTick)
    this.timerTick = setTimeout(() => this.paintTimer(), delay)
  }

  formatCountdown(remainingMs) {
    const remaining = Number(remainingMs)
    const totalSeconds = !Number.isFinite(remaining) || remaining <= 0 ? 0 : Math.ceil(remaining / 1000)
    const minutes = Math.floor(totalSeconds / 60)
    const seconds = totalSeconds % 60
    return `${minutes}:${String(seconds).padStart(2, "0")}`
  }

  finishByTimer() {
    if (!this.alive || this.busy || this.inflight || this.finishing) return
    const form = this.element.querySelector("form[data-timer-finish]")
    if (!form) return
    this.finishing = true
    if (typeof form.requestSubmit === "function") {
      form.requestSubmit()
    } else {
      form.querySelector("[type=submit]")?.click()
    }
  }

  async submit(event) {
    const form = event.target
    if (!(form instanceof HTMLFormElement)) return
    if (form.hasAttribute("data-live-off")) return
    event.preventDefault()

    const submitter = event.submitter
    const body = submitter ? new FormData(form, submitter) : new FormData(form)
    if (submitter && submitter.name) body.set(submitter.name, submitter.value)

    const buttons = Array.from(form.querySelectorAll("button, input[type=submit]"))
    buttons.forEach((button) => { button.disabled = true })
    this.busy = true

    const abort = new AbortController()
    const timeout = setTimeout(() => abort.abort(), 15000)
    try {
      const response = await fetch(form.action, {
        method: (form.method || "post").toUpperCase(),
        body,
        headers: {
          Accept: "application/json",
          "X-CSRF-Token": document.querySelector("meta[name='csrf-token']")?.content || ""
        },
        credentials: "same-origin",
        signal: abort.signal
      })
      if (!response.ok) throw new Error(String(response.status))
      this.applyFull(await response.json())
    } catch (_error) {
      buttons.forEach((button) => { button.disabled = false })
      this.finishing = false
    } finally {
      clearTimeout(timeout)
      this.busy = false
    }
  }
}
